package com.music.bitchord.playback.smart

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

class LoopCrownQualificationTest {
    private val clearLyrics = emptyList<LoopMix.Span>()

    // Independent literal schedule inputs, never a plan regenerated by the planner under test.
    private fun pick(bpm: Double, start: Double = 0.5): LoopMix.Pick {
        val beat = 60.0 / bpm
        return LoopMix.Pick(start, start + 16.0 * beat, 4, beat, bpm, 0.0, LoopMix.Check.MASK)
    }

    private fun crown(
        outBpm: Double = 120.0,
        inBpm: Double = 120.0,
        fold: Double = 1.0,
        rampBars: Int = 2,
        exitBars: Int = 2,
        totalBars: Int = 8,
    ) = LoopMix.Plan(
        out = pick(outBpm, 190.5),
        inn = pick(inBpm),
        fold = fold,
        enterBars = 4,
        rampBars = rampBars,
        exitBars = exitBars,
        totalBars = totalBars,
    )

    private fun assertFiniteSummaries(qualification: LoopMix.CrownQualification) {
        assertTrue(
            listOf(qualification.outMinRate, qualification.outMaxRate, qualification.inMinRate, qualification.inMaxRate)
                .filterNotNull().all { it.isFinite() },
            "No non-finite numerical summaries may escape into telemetry",
        )
    }

    private fun assertRefused(plan: LoopMix.Plan, code: String): LoopMix.CrownQualification {
        val qualification = LoopMix.qualifyCrown(plan)
        assertFalse(qualification.accepted)
        assertEquals(code, qualification.refusal)
        assertFiniteSummaries(qualification)
        return qualification
    }

    private fun assertAccepted(plan: LoopMix.Plan): LoopMix.CrownQualification {
        val qualification = LoopMix.qualifyCrown(plan)
        assertTrue(qualification.accepted, "refusal=${qualification.refusal}")
        assertNull(qualification.refusal)
        assertFiniteSummaries(qualification)
        val clock = LoopMix.Clock(plan)
        assertEquals(1.0, clock.tempo(clock.beats - 1) / plan.inn.bpm * plan.fold, 1e-9)
        val loops = (clock.inReleasePosition - plan.inn.loopStart) / (plan.inn.loopEnd - plan.inn.loopStart)
        assertEquals(kotlin.math.round(loops), loops, 1e-9)
        return qualification
    }

    @Test
    fun nonCrownsHaveAnExplicitRefusalWithoutNumericalSummaries() {
        val base = crown().copy(out = crown().out.copy(bpm = Double.NaN))
        for (plan in listOf(base.copy(outLoops = false), base.copy(inLoops = false), base.copy(outLoops = false, inLoops = false))) {
            val qualification = assertRefused(plan, "not-crown")
            assertNull(qualification.outMinRate)
            assertNull(qualification.outMaxRate)
            assertNull(qualification.inMinRate)
            assertNull(qualification.inMaxRate)
            assertNull(qualification.requiredRampBars)
        }
    }

    @Test
    fun protectedWideAndFoldedRampsRemainExecutable() {
        val cases = listOf(
            crown(120.0, 134.0, rampBars = 6, totalBars = 12) to 6,
            crown(111.0, 169.0, fold = 2.0, rampBars = 11, exitBars = 3, totalBars = 18) to 11,
            crown(170.0, 80.0, fold = 0.5, rampBars = 4, exitBars = 8, totalBars = 16) to 4,
        )
        for ((plan, required) in cases) assertEquals(required, assertAccepted(plan).requiredRampBars)
    }

    @Test
    fun executionBoundariesAreInclusiveWithoutANewMusicalPercentageGate() {
        val slower = assertAccepted(crown(120.0, 90.0, rampBars = 12, exitBars = 4, totalBars = 20))
        assertEquals(0.75, assertNotNull(slower.outMinRate), 1e-9)
        assertEquals(1.3333333333333333, assertNotNull(slower.inMaxRate), 1e-9)
        val faster = assertAccepted(crown(120.0, 160.0, rampBars = 16, exitBars = 4, totalBars = 24))
        assertEquals(1.3333333333333333, assertNotNull(faster.outMaxRate), 1e-9)
        assertEquals(0.75, assertNotNull(faster.inMinRate), 1e-9)
    }

    @Test
    fun outgoingEndpointRejectsAReciprocalRateThatStillFits() {
        val qualification = assertRefused(
            crown(120.0, 89.4, rampBars = 13, exitBars = 3, totalBars = 20), "execution-rate",
        )
        assertEquals(0.745, assertNotNull(qualification.outMinRate), 1e-9)
        assertEquals(1.3422818791946309, assertNotNull(qualification.inMaxRate), 1e-9)
    }

    @Test
    fun incomingReciprocalEndpointRejectsWhatOutgoingEnvelopeAloneWouldAllow() {
        val qualification = assertRefused(
            crown(120.0, 160.8, rampBars = 17, exitBars = 3, totalBars = 24), "execution-rate",
        )
        assertEquals(1.34, assertNotNull(qualification.outMaxRate), 1e-9)
        assertEquals(0.7462686567164179, assertNotNull(qualification.inMinRate), 1e-9)
    }

    @Test
    fun nonFiniteAndInconsistentPickGeometryIsRefused() {
        val base = crown()
        val invalid = listOf(
            base.out.copy(loopStart = Double.NaN),
            base.out.copy(loopStart = -0.5),
            base.out.copy(loopEnd = Double.POSITIVE_INFINITY),
            base.out.copy(loopEnd = base.out.loopStart),
            base.out.copy(bars = 0),
            base.out.copy(bars = 3),
            base.out.copy(beatSec = 0.0),
            base.out.copy(beatSec = Double.NaN),
            base.out.copy(bpm = Double.NEGATIVE_INFINITY),
            base.out.copy(bpm = 132.0),
            base.out.copy(loopEnd = 198.6),
        )
        for (pick in invalid) assertRefused(base.copy(out = pick), "invalid-out-pick")
        assertRefused(base.copy(inn = base.inn.copy(beatSec = 0.6)), "invalid-in-pick")
    }

    @Test
    fun unsupportedAndNonFiniteFoldsAreRefused() {
        for (fold in listOf(0.0, -1.0, 3.0, Double.NaN, Double.POSITIVE_INFINITY)) {
            val qualification = assertRefused(crown().copy(fold = fold), "unsupported-fold")
            assertNull(qualification.outMinRate)
            assertNull(qualification.requiredRampBars)
        }
    }

    @Test
    fun uncomputableRatesAndRampSummariesStayNullRatherThanNonFinite() {
        val overflow = crown().copy(out = pick(1e308, 0.0), inn = pick(1e308, 0.0), fold = 0.5)
        val invalidRates = assertRefused(overflow, "invalid-rates")
        assertNull(invalidRates.outMaxRate)
        assertNull(invalidRates.inMinRate)
        assertNull(invalidRates.requiredRampBars)
        val excessive = crown().copy(out = pick(1e12, 0.0), inn = pick(1.2e12, 0.0))
        val invalidRamp = assertRefused(excessive, "ramp-budget")
        assertEquals(1.2, assertNotNull(invalidRamp.outMaxRate), 1e-9)
        assertNull(invalidRamp.requiredRampBars)
    }

    @Test
    fun invalidClockInputsAreRefusedBeforeClockAllocation() {
        val base = crown()
        val invalid = listOf(
            base.copy(enterBars = -1),
            base.copy(rampBars = 1),
            base.copy(rampBars = Int.MAX_VALUE),
            base.copy(exitBars = -1),
            base.copy(targetBpmOverride = Double.NaN),
            base.copy(targetBpmOverride = 132.0),
            base.copy(nativeIncoming = true),
            base.copy(incomingHoldSec = Double.POSITIVE_INFINITY),
            base.copy(incomingHoldSec = -0.5),
            base.copy(faderSwapBeats = Double.NaN),
        )
        for (plan in invalid) assertRefused(plan, "invalid-clock")
        // A positive local tempo cannot be silently replaced by Clock's defensive 1 BPM floor.
        assertRefused(crown(0.5, 0.5), "invalid-clock")
    }

    @Test
    fun malformedOrPartialIncomingLoopReleaseIsRefused() {
        val base = crown()
        for (plan in listOf(
            base.copy(totalBars = Int.MAX_VALUE),
            base.copy(totalBars = 9, exitBars = 3),
            base.copy(exitBars = 3),
            base.copy(incomingHoldSec = 0.5),
            base.copy(incomingHoldSec = 20.0),
        )) assertRefused(plan, "invalid-release")
    }

    @Test
    fun excessiveUnclampedRampRequirementCannotHideBehindTwentyFourBars() {
        val atBudget = crown(300.0, 360.0, rampBars = 24, exitBars = 4, totalBars = 32)
        assertEquals(24, assertAccepted(atBudget).requiredRampBars)
        val beyondBudget = crown(300.0, 370.0, rampBars = 24, exitBars = 4, totalBars = 32)
        val qualification = assertRefused(beyondBudget, "ramp-budget")
        assertEquals(28, qualification.requiredRampBars)
        assertEquals(1.2333333333333334, assertNotNull(qualification.outMaxRate), 1e-9)
        assertEquals(0.8108108108108109, assertNotNull(qualification.inMinRate), 1e-9)
        assertEquals(12, assertRefused(crown(120.0, 150.0), "invalid-clock").requiredRampBars)
    }

    private fun analysis(localBpm: Double, duration: Double): TrackAnalysis {
        val frames = (duration * 10.0).toInt()
        return TrackAnalysis(
            status = TrackAnalysis.STATUS_READY,
            duration = duration,
            bpm = localBpm,
            beatInterval = 60.0 / localBpm,
            // Accepted constant-grid path: do not impose a new confidence cutoff.
            beatConfidence = 0.0,
            downbeats = listOf(0.5),
            firstBeat = 0.5,
            vocalProbability = 0.9,
            vocalWindows = listOf(CurveWindow(0.0, 10.0, FloatArray(frames) { 0.05f })),
            levelWindows = listOf(CurveWindow(0.0, 10.0, FloatArray(frames) { levelFromRms(0.3).toFloat() })),
        )
    }

    private fun missed() = crown().copy(out = pick(120.0, 182.5))

    private fun initial(out: TrackAnalysis, inn: TrackAnalysis, why: StringBuilder, sungOut: List<LoopMix.Span> = clearLyrics) =
        LoopMix.plan(out, 200.0, inn, 180.0, 0.0, sungOut, clearLyrics, why = why)

    private fun shifted(out: TrackAnalysis, inn: TrackAnalysis, why: StringBuilder, sungOut: List<LoopMix.Span> = clearLyrics) =
        LoopMix.shiftToNextBar(missed(), out, 200.0, inn, 180.0, sungOut, clearLyrics, why = why)

    @Test
    fun initialAndShiftedCrownsApplyTheSameRecoveryRuleOnAcceptedConstantGrids() {
        val out = analysis(120.0, 200.0)
        val inn = analysis(120.0, 180.0).copy(bpm = 132.0)
        assertTrue(shouldDeclineToMix(out, inn))
        val initialWhy = StringBuilder()
        val shiftWhy = StringBuilder()
        val first = assertNotNull(initial(out, inn, initialWhy))
        val next = assertNotNull(shifted(out, inn, shiftWhy))
        assertAccepted(first)
        assertAccepted(next)
        assertEquals(190.5, first.out.loopStart, 1e-9)
        assertEquals(184.5, next.out.loopStart, 1e-9)
        assertEquals(192.5, next.out.loopEnd, 1e-9)
        assertEquals(0.5, next.inn.loopStart, 1e-9)
        assertEquals(8.5, next.inn.loopEnd, 1e-9)
        assertEquals(4, next.out.bars)
        assertEquals(4, next.inn.bars)
        assertEquals(1.0, next.fold, 1e-9)
        assertEquals("", initialWhy.toString())
        assertEquals("", shiftWhy.toString())
    }

    @Test
    fun initialAndShiftedSearchesShareDecisiveExecutionAndRampRefusals() {
        for ((outBpm, inBpm, code) in listOf(
            Triple(120.0, 84.0, "execution-rate"),
            Triple(300.0, 372.0, "ramp-budget"),
        )) {
            val out = analysis(outBpm, 200.0)
            val inn = analysis(inBpm, 180.0)
            val initialWhy = StringBuilder()
            val shiftWhy = StringBuilder()
            assertNull(initial(out, inn, initialWhy))
            assertNull(shifted(out, inn, shiftWhy))
            assertEquals("crown: $code", initialWhy.toString())
            assertEquals("crown: $code", shiftWhy.toString())
        }
    }

    @Test
    fun wholeTrackRecoveryDoesNotBypassLocalSungCoverageQuietOrLyricVetoes() {
        val out = analysis(120.0, 200.0)
        val inn = analysis(120.0, 180.0).copy(bpm = 132.0)
        assertTrue(shouldDeclineToMix(out, inn))
        val unsafe = listOf(
            out.copy(vocalWindows = listOf(CurveWindow(0.0, 10.0, FloatArray(2000) { 0.9f }))) to "sung (mask)",
            out.copy(vocalWindows = listOf(CurveWindow(0.0, 10.0, FloatArray(100) { 0.05f }))) to "unmeasured",
            out.copy(levelWindows = listOf(CurveWindow(0.0, 10.0, FloatArray(2000) { 0f }))) to "quiet",
        )
        for ((analysis, reason) in unsafe) {
            val initialWhy = StringBuilder()
            val shiftWhy = StringBuilder()
            assertNull(initial(analysis, inn, initialWhy))
            assertNull(shifted(analysis, inn, shiftWhy))
            assertTrue(initialWhy.toString().startsWith("outgoing: "))
            assertTrue(initialWhy.contains(reason))
            assertTrue(shiftWhy.toString().startsWith("outgoing: "))
            assertTrue(shiftWhy.contains(reason))
        }
        val sung = listOf(LoopMix.Span(0.0, 200.0))
        assertNull(initial(out, inn, StringBuilder(), sung))
        assertNull(shifted(out, inn, StringBuilder(), sung))
    }
}
